  function matchesLevel(level, puzzle, rating) {
    var config = LEVELS[level];
    var clues = clueCount(puzzle);

    if (!rating.solved || rating.requiresBacktracking) {
      return false;
    }
    if (clues < config.minClues || clues > config.maxClues) {
