      return !hasAny(rating.techniques, SINGLES.slice(1)) &&
        !hasAny(rating.techniques, ADVANCED);
    }

    if (level === 'sprint') {
      // Les singletons cachés sont nécessaires, aucune technique avancée.
      return (
        rating.techniques.indexOf(TECHNIQUES.HIDDEN_SINGLE) !== -1 &&
        !hasAny(rating.techniques, ADVANCED)
