/* ---------- Livret ---------- */
.sheet{
  width:297mm;
  height:210mm;
  display:flex;
  background:var(--sable);
  overflow:hidden;
  position:relative;
}
.slot{width:148.5mm;height:210mm;overflow:hidden;position:relative}
.slot .page{width:148.5mm;height:210mm;margin:0}

/* ---------- Couverture / grille v2 (calqué sur case-depart-template-*.html) ----------
   Variables posées en inline-style par instance (--fond-couverture, --titre, etc.),
   pas globales : chaque thème (Halloween, Noël…) a ses propres couleurs ici,
   volontairement hors de la palette d'impression partagée du reste du carnet. */
.couverture{background-image:var(--illustration);background-size:100% 100%;background-blend-mode:multiply;background-color:var(--fond-couverture);color:var(--encre-couv)}
.couverture .grille{top:18.9%;--ext:.75mm;--fin:.6mm;--epais:1.05mm}
.edition{position:absolute;left:16.75%;top:15%;font-family:'Oswald',sans-serif;font-weight:400;font-size:7.3mm;line-height:1;letter-spacing:-.055em;white-space:nowrap}
.titre{position:absolute;left:15.95%;top:70.45%;width:68.3%;font-family:'Anton',sans-serif;font-weight:400;font-size:28.5mm;line-height:1;letter-spacing:-.056em;color:var(--titre);white-space:nowrap}
.nombre{position:absolute;left:15.85%;top:81.2%;font-family:'Oswald',sans-serif;font-weight:400;font-size:7.25mm;line-height:1;white-space:nowrap}

.page-grille{background:var(--fond-grille);color:var(--encre-grille)}
.page-grille .grille{top:22.9%;--ext:.95mm;--fin:.6mm;--epais:1.25mm}
.entete{position:absolute;left:15.55%;width:68.85%;top:15.1%;height:4.3%;display:flex;justify-content:space-between;align-items:flex-end;border-bottom:1mm solid currentColor;padding-bottom:1.35%;font-family:'Anton',sans-serif;font-weight:400;font-size:6.9mm;line-height:1;white-space:nowrap}
.pied span:last-child{letter-spacing:-.04em}
.pied{position:absolute;left:15.65%;width:68.6%;top:75.15%;display:flex;justify-content:space-between;align-items:baseline;font-family:'Oswald',sans-serif;font-weight:400;font-size:7.1mm;line-height:1;letter-spacing:-.012em;white-space:nowrap}

.grille{position:absolute;left:15.85%;width:68.3%;aspect-ratio:1/1;border:var(--ext) solid currentColor;border-radius:15mm;overflow:hidden;display:grid;grid-template-columns:repeat(9,1fr);grid-template-rows:repeat(9,1fr)}
.grille span{position:relative;display:flex;align-items:center;justify-content:center;border-right:var(--fin) solid currentColor;border-bottom:var(--fin) solid currentColor;font-family:'Oswald',sans-serif;font-weight:500;font-size:9mm;line-height:1}
.grille span.etoile::after{content:'★';position:absolute;top:.3mm;right:.6mm;font-size:3mm;line-height:1}
.grille span:nth-child(9n){border-right:none}
.grille span:nth-child(9n+3),.grille span:nth-child(9n+6){border-right-width:var(--epais)}
.grille span:nth-child(n+73){border-bottom:none}
.grille span:nth-child(n+19):nth-child(-n+27),
.grille span:nth-child(n+46):nth-child(-n+54){border-bottom-width:var(--epais)}

/* ---------- Écran / impression ---------- */
@media screen{
  body{padding:8mm 0}
  .page,.sheet{margin:0 auto 8mm}
}
@media print{
  body{padding:0}
  .page,.sheet{margin:0;break-after:page;page-break-after:always}
  .page:last-child,.sheet:last-child{break-after:auto;page-break-after:auto}
  .slot .page{break-after:auto;page-break-after:auto;margin:0}
}
`;
  }

  function validateFormat(format) {
    if (FORMATS.indexOf(format) === -1) {
      throw new Error(
        'Format inconnu : ' + format + '. Valeurs possibles : ' + FORMATS.join(', ') + '.'
      );
    }
  }

  /**
   * Construit le HTML complet d'un carnet.
   *
   * @param {object} carnet données produites par carnet.js
   * @param {{
   *   format?: 'A4'|'A5'|'A5-livret',
   *   gift?: {recipientName?: string, message?: string},
   *   buyerEmail?: string,
   *   includeCorrections?: boolean
   * }} [options]
   * @returns {string}
   */
  function buildHtml(carnet, options) {
    options = options || {};
    var format = options.format || 'A4';
    validateFormat(format);

    if (!carnet || !carnet.sections || !Array.isArray(carnet.sections)) {
      throw new Error('Carnet invalide : sections manquantes.');
    }

    var pages = [];
    var pageNumber = 1;
    var gridNumber = 0;

    pages.push(Couverture.page(carnet));
    pageNumber++;

    if (carnet.gift && carnet.gift.recipientName) {
      pages.push(CarteCadeau.page(carnet, options, pageNumber));
      pageNumber++;
    }

    pages.push(LigneDepart.page(carnet, options, pageNumber));
    pageNumber++;

    carnet.sections.forEach(function (section) {
      if (section.kind === 'grids') {
        section.grids.forEach(function (grid) {
          gridNumber++;
          pages.push(Grilles.page(carnet, options, section, grid, pageNumber, gridNumber));
          pageNumber++;
        });
      } else if (section.kind === 'theme') {
        var themeSection = {
          title: 'THÈME ' + section.index + ' · ' + section.theme.nom,
          arrows: ''
        };
        section.grids.forEach(function (grid) {
          gridNumber++;
          pages.push(Grilles.page(carnet, options, themeSection, grid, pageNumber, gridNumber));
          pageNumber++;
        });
      } else if (section.kind === 'coloriage') {
        pages.push(Ravitaillement.coloringPage(carnet, options, section, pageNumber));
        pageNumber++;
      } else if (section.kind === 'tirage') {
        pages.push(Ravitaillement.tiragePage(carnet, options, section, pageNumber));
        pageNumber++;
      }
    });

    if (carnet.finalGrid) {
      pages.push(Arrivee.page(carnet, options, pageNumber));
      pageNumber++;
    }

    if (options.includeCorrections !== false) {
      var perPage = format === 'A4' ? 6 : 4;
      var correctionPages = Corrections.pages(carnet, options, pageNumber, perPage);
      correctionPages.forEach(function (correctionPage) {
        pages.push(correctionPage);
        pageNumber++;
      });
    }

    var body;

    if (format === 'A5-livret') {
      var padded = Imposition.padToMultipleOf4(pages.length);
      while (pages.length < padded) {
        pages.push(Notes.page(carnet, options, pageNumber));
        pageNumber++;
      }

      var sides = Imposition.impositionOrder(pages.length);
      body = sides
        .map(function (pair) {
          return (
            '<div class="sheet">' +
            '<div class="slot">' +
            pages[pair[0] - 1] +
            '</div>' +
            '<div class="slot">' +
            pages[pair[1] - 1] +
            '</div>' +
            '</div>'
          );
        })
        .join('\n');
    } else {
      body = pages.join('\n');
    }

    var formatClass =
      format === 'A4' ? 'format-a4' : format === 'A5' ? 'format-a5' : 'format-livret';
    var title = carnet.title + ' — ' + carnet.edition;

    return (
      '<!doctype html>\n' +
      '<html lang="fr">\n' +
      '<head>\n' +
      '<meta charset="utf-8">\n' +
      '<meta name="viewport" content="width=device-width, initial-scale=1">\n' +
      '<meta name="generator" content="Case Départ — automation">\n' +
      '<title>' +
      H.escapeHtml(title) +
      '</title>\n' +
      '<style>\n' +
      baseCss(format) +
      '\n</style>\n' +
      '</head>\n' +
      '<body class="' +
      formatClass +
      '">\n' +
      body +
      '\n</body>\n</html>\n'
    );
  }

  return {
    FORMATS: FORMATS,
    buildHtml: buildHtml,
    baseCss: baseCss
  };
});



// ---------------------------------------------------------------------------
// Génère un PDF cadeau personnalisé (nom du destinataire + message).
// Le bundle Case Départ est injecté au-dessus par build-workflows.js.
// ---------------------------------------------------------------------------
const order  = $('Mapper le produit').first().json;
const Carnet   = CaseDepartCarnet;
const Template = CaseDepartTemplate;
const THEMES   = CASE_DEPART_THEMES;

// Récupère le carnet prêt depuis Supabase (nœud précédent)
const carnetRow = $('Lire le carnet').first().json;
if (!carnetRow || !carnetRow.id) {
  throw new Error('Carnet introuvable en base : ' + order.carnet_slug);
}

const themeKey = Object.keys(THEMES).find(function(k) {
  return THEMES[k].slug === carnetRow.theme || k === carnetRow.theme;
}) || carnetRow.theme;

const theme = Carnet.getTheme(THEMES, themeKey);

// Reconstruit le carnet depuis la BDD (metadata uniquement, pas les grilles)
const carnet = Carnet.buildCarnet({
  theme: theme,
  type: carnetRow.type,
  level: carnetRow.level || null,
  catalog: THEMES,
  slug: carnetRow.slug,
  edition: carnetRow.edition || 'Édition 2026',
  version: carnetRow.version || '1.0.0',
  counts: carnetRow.type === 'thematique' ? { echauffement: 10, sprint: 10, marathon: 10 } : null
});

const showBuyerEmail = String($env.BUYER_EMAIL_IN_FOOTER || 'false') === 'true';

const html = Template.buildHtml(carnet, {
  format: order.format,
  gift: {
    recipientName: order.recipient_name,
    message: order.gift_message
  },
  buyerEmail: showBuyerEmail ? order.buyer_email : null
});

const sessionId = order.stripe_session_id;
const fileName  = carnetRow.slug + '-' + order.format + '-gift-' + sessionId.slice(-8) + '.pdf';
const path      = 'commandes/' + sessionId + '/' + fileName;

return [{
  json: {
    html: html,
    fileName: fileName,
    path: path,
    format: order.format
  }
}];

// Normalise le lien signé quelle que soit la branche (standard ou cadeau).
// Les deux nœuds de signature renvoient { signedURL: '/storage/v1/...' }.
const signedURL = $json.signedURL;
if (!signedURL) throw new Error('Pas de lien signé dans la réponse Supabase Storage.');
const fullUrl = $env.SUPABASE_URL + '/storage/v1' + signedURL;

// Détermine le chemin stocké
let pdfPath;
try {
  pdfPath = $('Récupérer le chemin PDF standard').first().json.pdf_path;
} catch(e) {
  pdfPath = $('Générer le HTML cadeau').first().json.path;
}

return [{ json: { signed_url: fullUrl, pdf_path: pdfPath } }];
